def handle_filter_users(params: dict) -> tuple[int, dict]:
    """Filter users by any combination of the supported optional filters."""
    filters: dict = {}

    if "name_contains" in params:
        raw = params["name_contains"]
        if not isinstance(raw, str):
            return 400, {"error": "invalid filter"}
        value = raw.strip()
        if not 1 <= len(value) <= _NAME_MAX:
            return 400, {"error": "invalid filter"}
        filters["name_contains"] = value

    if "email_domain" in params:
        raw = params["email_domain"]
        if not isinstance(raw, str) or not _EMAIL_DOMAIN_RE.fullmatch(raw):
            return 400, {"error": "invalid filter"}
        filters["email_domain"] = raw

    for key in ("min_id", "max_id"):
        if key in params:
            raw = params[key]
            if not isinstance(raw, str) or not _DIGITS_RE.fullmatch(raw):
                return 400, {"error": "invalid filter"}
            filters[key] = int(raw)

    return 200, {"users": users.filter_users(**filters)}
